<template><div class="page"><div class="toolbar"><el-input v-model="q.keyword" placeholder="用户名、姓名、手机号或邮箱" clearable @keyup.enter.native="load"/><el-select v-model="q.roleCode" clearable placeholder="用户类型"><el-option v-for="r in roles" :key="r.value" :label="r.label" :value="r.value"/></el-select><el-select v-model="q.enabled" clearable placeholder="用户状态"><el-option label="启用" :value="true"/><el-option label="停用" :value="false"/></el-select><el-button type="primary" @click="load">查询</el-button><el-button type="success" @click="edit()">新增用户</el-button></div><el-table :data="rows" v-loading="loading"><el-table-column prop="username" label="用户名"/><el-table-column prop="displayName" label="姓名"/><el-table-column label="用户类型" width="110"><template slot-scope="s">{{roleName(s.row.roleCode)}}</template></el-table-column><el-table-column prop="application" label="所属应用" min-width="140"><template slot-scope="s">{{s.row.roleCode==='ADMIN'?'全部应用':(s.row.application||'-')}}</template></el-table-column><el-table-column prop="phone" label="手机号" min-width="130"/><el-table-column prop="email" label="邮箱" min-width="180"/><el-table-column label="状态" width="90"><template slot-scope="s"><el-switch :value="s.row.enabled" :disabled="s.row.username==='admin'" @change="status(s.row,$event)"/></template></el-table-column><el-table-column label="操作" width="170"><template slot-scope="s"><el-button size="mini" @click="edit(s.row)">编辑</el-button><el-button size="mini" type="danger" :disabled="s.row.username==='admin'" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-pagination class="pager" layout="total,prev,pager,next" :total="total" :page-size="q.pageSize" @current-change="p=>{q.pageNum=p;load()}"/><el-dialog :title="form.id?'编辑用户':'新增用户'" :visible.sync="visible" width="620px"><el-form :model="form" label-width="110px"><el-form-item label="用户名" required><el-input v-model="form.username" :disabled="form.username==='admin'"/></el-form-item><el-form-item label="外部用户ID"><el-input v-model="form.externalUserId" placeholder="测试案例平台用户唯一标识"/></el-form-item><el-form-item label="姓名" required><el-input v-model="form.displayName"/></el-form-item><el-form-item label="用户类型" required><el-select v-model="form.roleCode"><el-option v-for="r in roles" :key="r.value" :label="r.label" :value="r.value"/></el-select></el-form-item><el-form-item v-if="form.roleCode==='USER'" label="所属应用" required><el-input v-model="form.application" placeholder="普通用户只能扫描该应用"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled" :disabled="form.username==='admin'"/></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></span></el-dialog></div></template>
<script>import{userApi}from'../api';const empty=()=>({username:'',externalUserId:'',displayName:'',roleCode:'USER',application:'',phone:'',email:'',description:'',enabled:true});export default{name:'UserView',data:()=>({q:{keyword:'',roleCode:'',enabled:null,pageNum:1,pageSize:20},roles:[{label:'管理员',value:'ADMIN'},{label:'普通用户',value:'USER'}],rows:[],total:0,loading:false,visible:false,saving:false,form:empty()}),created(){this.load()},methods:{roleName(v){const r=this.roles.find(x=>x.value===v);return r?r.label:v},async load(){this.loading=true;try{const r=await userApi.page(this.q);this.rows=r.list;this.total=r.total}finally{this.loading=false}},edit(row){this.form=row?Object.assign(empty(),row):empty();this.visible=true},async save(){if(!/^[A-Za-z][A-Za-z0-9_.-]{2,63}$/.test(this.form.username))return this.$message.warning('用户名须以字母开头，长度3-64位');if(!this.form.displayName.trim())return this.$message.warning('请填写姓名');if(this.form.roleCode==='USER'&&!this.form.application.trim())return this.$message.warning('普通用户必须指定所属应用');if(this.form.roleCode==='ADMIN')this.form.application='';if(this.form.phone&&!/^[0-9+() -]{6,32}$/.test(this.form.phone))return this.$message.warning('手机号格式不正确');if(this.form.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(this.form.email))return this.$message.warning('邮箱格式不正确');this.saving=true;try{if(this.form.id)await userApi.update(this.form.id,this.form);else await userApi.create(this.form);this.visible=false;this.$message.success('用户保存成功');await this.load()}finally{this.saving=false}},async status(row,enabled){await userApi.status(row.id,enabled);row.enabled=enabled},async remove(row){await this.$confirm('确认删除用户 '+row.username+'？');await userApi.remove(row.id);this.$message.success('删除成功');await this.load()}}}</script>
